def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1

    trans_dc = 0
    trans_dd = 0
    punished = 0
    soft_follows = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        po = history[i - 1][1]
        cm = history[i][0]
        co = history[i][1]

        if pm == 'D':
            if co == 'C':
                trans_dc += 1
            else:
                trans_dd += 1

        if pm == 'D' and po == 'C' and cm == 'C' and co == 'D':
            punished += 1
        if pm == 'D' and po == 'C' and cm == 'C' and co == 'C':
            soft_follows += 1

    opp_c_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_run += 1
        else:
            break

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    my_c_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_run += 1
        else:
            break

    my_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_run += 1
        else:
            break

    mut_c_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'C':
            mut_c_run += 1
        else:
            break

    mut_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mut_d_run += 1
        else:
            break

    recent10_len = n if n < 10 else 10
    recent10_opp_c = 0
    for i in range(n - recent10_len, n):
        if history[i][1] == 'C':
            recent10_opp_c += 1

    opp_rate = opp_c / n
    last_m = history[-1][0]
    last_o = history[-1][1]

    # If the opponent has literally never defected, use a short probe/forgive test,
    # then exploit only if they remain cooperative when we return to C.
    if opp_c == n:
        exploit = False
        if n >= 2:
            h0 = history[-1]
            h1 = history[-2]
            if h0 == ('D', 'C') and h1 == ('D', 'C'):
                exploit = True
            if h0 == ('C', 'C') and h1 == ('D', 'C'):
                exploit = True
        if n >= 3:
            h0 = history[-1]
            h1 = history[-2]
            h2 = history[-3]
            if h0 == ('D', 'C') and h1 == ('C', 'C') and h2 == ('D', 'C'):
                exploit = True

        if exploit:
            return 'D'

        # Avoid opening a fresh exploit too late; leave enough time for recovery.
        if n <= 80 and mut_c_run >= 18:
            return 'D'

        # First untested defection against an apparently cooperative opponent: test.
        if n >= 2 and history[-1] == ('D', 'C') and history[-2] == ('C', 'C'):
            return 'C'

        return 'C'

    # Opponent defected last round.
    if last_o == 'D':
        # Clearly hostile: take the safe 1 rather than the 0.
        if opp_rate < 0.35:
            return 'D'

        # Forgiving early defection streaks is essential against TFT-style probes.
        if my_c_run >= 1 and opp_d_run <= 6 and opp_rate > 0.65:
            return 'C'

        # If we defected and they defected, try to break mutual defection against
        # cooperative opponents, but not against hard opponents.
        if last_m == 'D' and mut_d_run >= 1 and opp_rate > 0.60 and opp_d_run <= 3:
            return 'C'

        # Sustained recent defection is not a one-round mistake.
        if opp_d_run >= 3 or recent10_opp_c <= 3:
            return 'D'

        # Mixed opponents: cooperate once or twice if they still look valuable.
        if last_m == 'C':
            if opp_rate > 0.5 and recent10_opp_c >= 5:
                return 'C'
            return 'D'

        return 'D'

    # Opponent cooperated last round.
    if last_m == 'D':
        # The first D after long mutual cooperation is treated as a probe:
        # cooperate once to see whether the opponent retaliates.
        if n >= 2 and history[-2] == ('C', 'C') and trans_dc <= 1 and soft_follows == 0 and punished == 0:
            return 'C'

        # Already in an exploitation pattern: continue.
        if n >= 2 and history[-2] == ('D', 'C'):
            return 'D'
        if n >= 3 and history[-2] == ('C', 'C') and history[-3] == ('D', 'C'):
            return 'D'

        # If our D has not produced punishment and the opponent is still
        # broadly cooperative, keep exploiting the non-punishing response.
        if trans_dd == 0 and opp_rate > 0.5:
            return 'D'

        # A longer unbroken defection/exploit streak is also acceptable.
        if my_d_run >= 2 or opp_c_run >= 2:
            return 'D'

        return 'C'

    # Last round was (C,C).
    # If a probe was followed by cooperation rather than retaliation, exploit.
    if n >= 2 and history[-2] == ('D', 'C') and trans_dd == 0 and soft_follows > 0 and opp_rate > 0.45:
        return 'D'

    # Conservative second probe for opponents that defected once or a few times
    # early but have been very cooperative since. This can catch AllCoop-like
    # phases without trapping us with TFT.
    if (
        n >= 25 and n <= 80 and
        punished == 0 and trans_dd == 0 and
        my_c_run >= 10 and mut_c_run >= 10 and
        recent10_opp_c == 10 and opp_rate > 0.75
    ):
        return 'D'

    return 'C'
